/* Real page addresses: /{nl|fr|en}/..., one per page and language. Internally a page is still a short route name. */
const URL_LANGS=["nl","fr","en"].concat(Object.keys(window.EVI18N||{})), SEG={finder:"cable-finder",calc:"bereken-je-voordeel",etappro:"etappro",support:"support",about:"about",terms:"terms",privacy:"privacy",checkout:"checkout",done:"order-confirmed",paytest:"test-payment"}, SEG_R=Object.fromEntries(Object.entries(SEG).map(([k,v])=>[v,k]));
const slug=x=>String(x).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
const urlLang=()=>URL_LANGS.includes(S.lang)?S.lang:"en";
function pathOf(r,l){l=l||urlLang(); r=r||"home"; let p="";
  if(r==="shop")p="shop/"; else if(r.startsWith("cat-"))p="shop/"+r.slice(4)+"/"; else if(/^p-\d+$/.test(r)){const pr=PID[+r.slice(2)]; p="p/"+(pr?slug(pr.n[l]||pr.n.en)+"-":"")+r.slice(2)+"/";} else if(SEG[r])p=SEG[r]+"/";
  return "/"+l+"/"+p;}
function parsePath(){const s=location.pathname.split("/").filter(Boolean); const l=URL_LANGS.includes(s[0])?s[0]:null; const a=l?s.slice(1):s; let r="home";
  if(a[0]==="shop")r=a[1]&&GROUPS.includes(a[1])?"cat-"+a[1]:"shop"; else if(a[0]==="p"&&a[1]){const m=a[1].match(/(\d+)$/); r=m?"p-"+m[1]:"shop";} else if(SEG_R[a[0]])r=SEG_R[a[0]];
  return {l,r};}
function route(){return parsePath().r;}
function nav(r,replace){const u=pathOf(r); if(u!==location.pathname)history[replace?"replaceState":"pushState"]({}, "", u); closeAll(); go(); window.scrollTo(0,0);}
function fixLinks(){document.querySelectorAll('a[href^="#"]').forEach(a=>{const r=a.getAttribute("href").slice(1); if(a.dataset.act||!r)return; a.dataset.r=r; a.setAttribute("href",pathOf(r));});}
// the language in the address wins over the remembered one
(function(){const {l,r}=parsePath(); let keep=null; try{keep=sessionStorage.getItem("evck-lang")}catch(e){}
  if((r==="done"||r==="paytest")&&keep&&URL_LANGS.includes(keep)&&keep!==l){S.lang=keep; history.replaceState({},"",pathOf(r,keep)+location.search); return;}
  if(l&&(URL_LANGS.includes(S.lang)?S.lang!==l:l!=="en"))S.lang=l;})();
