function card(p){const from=(p.a||[]).some(a=>a.v.some(v=>v.x)); return `<a class="card" href="#p-${p.id}">${promoOn(p)?`<span class="tag promo">−${PROMO.pct}%</span>`:p.r?`<span class="tag">${t("r_"+p.r)}</span>`:""}${photo(p.i[0],L(p.n))}<div class="body"><h3>${esc(L(p.n))}</h3><div class="p">${from?`<small>${t("from")}</small> `:""}${promoOn(p)?`<s>${money(shown(grossFull(p)))}</s>`:p.c?`<s>${money(shown(p.c))}</s>`:""}${money(shown(gross(p)))}</div>${promoOn(p)?`<div class="promoline">${promoTxt("promo_short")}</div>`:""}</div></a>`;}

