  $("fCountry").onchange=e=>setCountry(e.target.value);
  if(isC){const v=$("fVat"),chk=()=>{S.co.vat=v.value.replace(/[\s.\-]/g,"").toUpperCase(); const re=VATRE[S.country]; S.co.vatValid=!!(re&&re.test(S.co.vat)); const st=$("vatState"); if(!S.co.vat){st.textContent="";st.className="vat-state";} else if(S.co.vatValid){st.textContent=S.country==="BE"?t("vat_ok_be"):t("vat_checking");st.className="vat-state ok";
      if(S.country!=="BE"){const asked=S.co.vat, cc=S.country; clearTimeout(chk.tm); chk.tm=setTimeout(()=>shopApi("/vat-check",{country:cc,vat:asked}).then(r=>{ if(S.co.vat!==asked||S.country!==cc||!$("vatState"))return; const s2=$("vatState");
        if(r.valid===true){s2.textContent=t("vat_vies_ok");s2.className="vat-state ok";} else if(r.valid===false){S.co.vatValid=false;s2.textContent=t("vat_vies_bad");s2.className="vat-state bad";renderCoSummary();renderChrome();renderCart();} else {s2.textContent=t("vat_vies_na");s2.className="vat-state";} }).catch(()=>{}),600);} } else{st.textContent=t("vat_bad",{c:cname(S.country),ex:exVat});st.className="vat-state bad";} renderCoSummary(); renderChrome(); renderCart();}; v.addEventListener("input",chk); chk();}
