function renderCoSummary(){
  const tt=totals(S.co.deliv);
  $("coSum").innerHTML=`<div class="eyebrow">${t("sum_order")}</div><table class="totals">${S.cart.map(l=>{const p=PID[l.pid];return `<tr><td>${l.qty}× ${esc(L(p.n))}<div class="note">${esc(variantText(p,l.sel))}</div></td><td class="num">${money(lineEx(l)*l.qty)}</td></tr>`}).join("")}
   <tr><td>${t("sub")} <span class="note">${t("excl")}</span></td><td class="num">${money(tt.sub)}</td></tr><tr><td>${t("ship")}</td><td class="num">${tt.free?t("free"):money(tt.ship)}</td></tr>
   <tr><td>${tt.r?t("vat_line",{r:String(tt.r).replace(".",S.lang==="en"?".":",")}):(S.buyer==="company"&&S.co.vatValid&&EU.has(S.country)?t("rc"):t("export"))}</td><td class="num">${money(tt.vat)}</td></tr><tr class="grand"><td>${t("total")}</td><td class="num">${money(tt.total)}</td></tr></table>
   <button class="btn" id="placeBtn" ${$("fTerms")?.checked?"":"disabled"}>${t("place")} · ${money(tt.total)}</button><p class="note" style="margin:0">${L(PAY_NAME[S.co.pay])} · Mollie</p><p class="co-msg" id="coMsg" role="alert"></p>`;
  $("placeBtn").onclick=async e=>{e.preventDefault(); const b=$("placeBtn"), v=id=>($(id)?.value||"").trim(), msg=m=>{$("coMsg").textContent=m||"";};
    const cust={company:v("fCo"),first:v("fFn"),last:v("fLn"),email:v("fEm"),phone:v("fPh"),street:v("fSt"),zip:v("fZip"),city:v("fCity")};
    const need=[["first","fFn"],["last","fLn"],["email","fEm"],["street","fSt"],["zip","fZip"],["city","fCity"],...(S.buyer==="company"?[["company","fCo"]]:[])].filter(([k])=>!cust[k]);
    document.querySelectorAll("#coForm .bad").forEach(x=>x.classList.remove("bad"));
    if(need.length){need.forEach(([,id])=>$(id)?.classList.add("bad")); $(need[0][1])?.focus(); msg(t("co_err_missing",{f:need.map(([k])=>t("f_"+k)).join(", ")})); return;}
    b.disabled=true; msg(t("co_wait"));
    try{const r=await shopApi("/order",{country:S.country,buyer:S.buyer,vat:S.buyer==="company"?S.co.vat:"",deliv:S.co.deliv,pay:S.co.pay,lang:["nl","fr","en"].includes(urlLang())?urlLang():"en",terms:!!$("fTerms")?.checked,customer:cust,items:S.cart.map(l=>({pid:l.pid,sel:l.sel,qty:l.qty}))});
      dl({event:"add_payment_info",ecommerce:{currency:"EUR",value:r.total}}); try{sessionStorage.setItem("evck-order",r.token);sessionStorage.setItem("evck-lang",urlLang())}catch(_){}
      location.href=r.checkoutUrl;
    }catch(err){b.disabled=false; msg(err.code==="missing"?t("co_err_missing",{f:String(err.detail||"").split(",").map(k=>t("f_"+k)).join(", ")}):err.code==="email"?t("co_err_email"):err.code==="vat_invalid"?t("co_err_vat"):err.code==="vat_unverified"?t("co_err_vies"):t("co_err")); if(err.code==="email")$("fEm")?.classList.add("bad");}
  };
}
function orderToken(){return new URLSearchParams(location.search).get("o")||"";}
let doneTimer=null;
function renderDone(){const tok=orderToken(), w=$("v-done"); clearTimeout(doneTimer);
  if(!tok||window.__PRERENDER){w.innerHTML=`<div class="wrap done"><h1>${t("st_none")}</h1><p><a class="btn" href="#shop">${t("back")}</a></p></div>`;return;}
  w.innerHTML=`<div class="wrap done"><div class="eyebrow">${t("st_checking")}</div></div>`; let tries=0;
  const load=()=>shopApi("/status?o="+encodeURIComponent(tok)).then(o=>{ if(route()!=="done"||orderToken()!==tok)return; const n=esc(o.number), list=`<ul class="list" style="margin:18px 0">${o.lines.map(l=>`<li>${l.qty}× ${esc(l.name)}${l.options.length?` <span class="muted">· ${esc(l.options.join(" · "))}</span>`:""}</li>`).join("")}</ul>`;
    if(o.status==="paid"){ if(S.cart.length){S.cart=[];save();renderCart();} dl({event:"purchase",ecommerce:{transaction_id:o.number,currency:"EUR",value:o.total}});
      w.innerHTML=`<div class="wrap done"><div class="eyebrow">✓ ${n}</div><h1 style="margin-top:10px">${t("st_paid_t",{n})}</h1><p class="muted" style="font-size:1.08rem">${t("done_p")}</p>${list}<table class="totals" style="max-width:360px"><tr class="grand"><td>${t("st_total")}</td><td class="num">${money(o.total)}</td></tr></table><p class="note">${t("st_sent")} ${esc(o.email)}</p>${o.test?"":`<div class="notice">${t("done_portal")}</div>`}<a class="btn" href="#shop">${t("back")}</a></div>`;}
    else if(o.status==="open"||o.status==="pending"){ w.innerHTML=`<div class="wrap done"><div class="eyebrow">${n}</div><h1 style="margin-top:10px">${t("st_open_t",{n})}</h1><p class="muted">${t("st_open_p")}</p></div>`; if(++tries<40)doneTimer=setTimeout(load,3000); }
    else w.innerHTML=`<div class="wrap done"><div class="eyebrow">${n}</div><h1 style="margin-top:10px">${t("st_failed_t",{n})}</h1><p class="muted" style="font-size:1.08rem">${t("st_failed_p")}</p><a class="btn" href="#checkout">${t("st_again")}</a></div>`;
  }).catch(()=>{w.innerHTML=`<div class="wrap done"><h1>${t("st_none")}</h1><p><a class="btn" href="#shop">${t("back")}</a></p></div>`;});
  load();}
function renderPayTest(){const tok=orderToken(), w=$("v-paytest");
  w.innerHTML=`<div class="wrap done"><div class="eyebrow">${t("tp_eb")}</div><h1 style="margin:10px 0 10px">${t("tp_h")}</h1><p class="muted">${t("tp_p")}</p><div id="tpInfo" class="notice" style="display:none"></div><div class="tp-btns">${["paid","failed","canceled","expired"].map(k=>`<button class="btn${k==="paid"?"":" ghost"}" data-tp="${k}">${t("tp_"+k)}</button>`).join("")}</div></div>`;
  if(!tok||window.__PRERENDER)return;
  shopApi("/status?o="+encodeURIComponent(tok)).then(o=>{const i=$("tpInfo"); if(!i)return; i.style.display=""; i.innerHTML=`${t("tp_order")} <b>${esc(o.number)}</b> · ${t("tp_amount")} <b>${money(o.total)}</b>`;}).catch(()=>{});
  w.querySelectorAll("[data-tp]").forEach(b=>b.onclick=()=>{w.querySelectorAll("[data-tp]").forEach(x=>x.disabled=true); shopApi("/simulate",{token:tok,result:b.dataset.tp}).finally(()=>{history.pushState({},"",pathOf("done")+"?o="+encodeURIComponent(tok)); go(); window.scrollTo(0,0);});});
}

/* ============ REVIEW & BUILD NOTES ============ */
function renderNotes(){
  const noDesc=PR.filter(p=>!p.d.en).length, noPhoto=PR.filter(p=>!p.i.length).map(p=>p.n.en);
  const ship=Object.keys(SHIP).sort((a,b)=>cname(a).localeCompare(cname(b))).map(c=>{const r=SHIP[c];return `<tr><td>${esc(cname(c))}</td><td class="n">${EU.has(c)?VAT[c]+"%":"0% (export)"}</td><td>${CARRIER(c)}</td><td class="n">${r.home==null?"–":money(r.home)}</td><td class="n">${r.pickup==null?"–":money(r.pickup)}</td><td>${FREE_SHIP.countries.has(c)?"≥ "+money(FREE_SHIP.over):""}</td><td>${r.tbc?'<span class="tbc">TO CONFIRM</span>':"Odoo orders"}</td></tr>`}).join("");
  const li=a=>`<ul class="list prose">${a.map(x=>`<li>${x}</li>`).join("")}</ul>`;
  $("v-notes").innerHTML=`<div class="wrap" style="padding-top:34px;padding-bottom:60px"><div class="prose"><div class="eyebrow">For Steve and the Odoo developer · English only</div><h1 style="margin:8px 0 12px">Review &amp; build notes</h1>
  <p>This version replaces the first prototype. Everything customer-facing now comes from the live evchargeking.com (crawled 14 Nov 2026 in Dutch, English and French) and from the Odoo database <b>evck.odoo.com</b>: ${PR.length} products with their real names, prices, variants, price extras, photos and descriptions, plus the home, ETAPpro, support, contact, terms and privacy content. It still takes no orders and sends no forms.</p></div>
  <h2 style="margin:30px 0 12px">What was wrong with the first prototype</h2>${li([
   "<b>Branding.</b> It used a copper colour and a typed logo. Now: the Belinus design system (black core surface, Arial Nova light headings, Space Grotesk capitals, pill buttons, light theme available) carrying the EVChargeking identity: the real EVChargeking wordmark, the EVChargeking blue #080DD4 as the only accent colour (a lighter tint of it for text and outlines on black), the real product photos, and “A belinus group company” in the header, footer, home and About. Belinus blue #2EB9EA appears in one place only: the Belinus group band on the home page. Arial Nova is licensed by Monotype: check that the Belinus web licence covers evchargeking.com. Space Grotesk must be self-hosted at launch.",
   "<b>End-of-year promotion.</b> 15% off the ETAPpro 11 until 31 December 2026, webshop orders only. In Odoo this must be a rule on the <i>website</i> pricelist (or a website-only promotion programme), so quotes, phone and e-mail orders keep the normal price. The prototype shows it in the top strip, a band on the home page, the shop card and the product page, and switches itself off after the end date.",
   "<b>Products.</b> 32 hand-written products with invented descriptions and drawings. Now: all 48 products in the live shop with their own photos and texts. Missing before: ETAPpro 7, the e-TAP 7.4 kW mobile charger, the Ohmy poles and bases, the electric cable per metre, the Type 3 connector and others.",
   "<b>Prices.</b> It assumed one price per extra metre for every length from 2 to 20 m. The live shop sells fixed lengths with fixed extras (up to 35 m for Type 2). Now every length, colour and option is a real variant with its real price.",
   "<b>Pages.</b> No product pages, no ETAPpro page, no customer support or service ticket, no terms, no privacy page. All are in now.",
   "<b>Languages.</b> It offered German without any German product content. Now Dutch, English and French, as on the live site. German needs translations first."])}
  <h2 style="margin:30px 0 12px">Problems in the current site and Odoo data</h2>${li([
   "<b>No product references.</b> None of the products or variants in Odoo has an internal reference or barcode. The product pages show the Odoo ID until real references are set.",
   `<b>${noPhoto.length} products have no photo:</b> ${noPhoto.map(esc).join(", ")}.`,
   `<b>${noDesc} of ${PR.length} products have no description</b> on the live site, among them the Type 2 7.4 kW cable, the Type 1 cable, both plain pigtails, the CTAPpro sensors and the storage bag.`,
   "<b>Mixed languages.</b> The English pages of the Bespoke Tesla cable and the ETAPpro 11 contain Dutch paragraphs; the MTAP page carried a “Translated with DeepL (free version)” line (removed here). Five product names were Dutch in English and French (CEE sockets, Muurbeugel Kit, Ohmy montagepaal) and one had a typo (“charking”). They are renamed here; fix them in Odoo.",
   "<b>Legal texts.</b> Terms exist in Dutch only and name “Some bvba”; the privacy page names “Some BV”, gives an older address (Probastraat 21, 2235 Westmeerbeek) next to Probastraat 21, 2235 Westmeerbeek, and a register number 838 249 337 that does not match VAT BE 0829.249.337. Both texts are carried over unchanged and need a legal update, including the Belinus group.",
   "<b>Returns.</b> The terms give 14 days and allow excluding made-to-specification products, but no product page says whether a cable cut to length can be returned. Decide and state it.",
   "<b>Leftovers on the live site.</b> An unconfigured Odoo snippet message on the home and ETAPpro pages and the ETAPpro text repeated three times in the page source.",
   "<b>Price steps.</b> Some length extras are off by a cent or more (6 m +€52.01, 10 m +€80.01, 25 m +€298.98, 14 m +€119.94). Worth rounding in Odoo.",
   "<b>Stock.</b> Cables show negative stock in Odoo (made to order without manufacturing orders). This shop shows “made to order” for cables and “in stock” only where Odoo has a positive quantity. ETAPpro 7 has zero stock while on sale.",
   "<b>Hidden duplicates.</b> “Wallbracket” and an installer-contact request are published in Odoo but not listed in the shop; “Wallbracket” duplicates the wall bracket kit.",
   "<b>“Awarded” ribbon.</b> The ETAPpro carries it without saying which award. Name it."])}
  <h2 style="margin:30px 0 12px">New compared with the live shop</h2>${li([
   "<b>Cable finder</b> on the home page and its own page: connector, power, length, colour. It always lands on a real product variant.",
   "<b>Account at checkout.</b> The customer fills in the order details and chooses private or company; on placing the order an account is created automatically in the Belinus service portal with that email address, and an email invites the customer to set a password and follow the order there. No password is asked in the shop. Returning customers are matched on their email address. Companies enter a VAT number that is checked, with reverse charge for EU companies outside Belgium. There is no B2B/B2C switch while browsing: prices show incl. VAT of the delivery country. To build: the order confirmation in Odoo triggers the portal account and the invitation email. Tell the customer before ordering that an account is created (the checkout does), and have the lawyer confirm the automatic account against the data-protection authorities' guidance on mandatory accounts.",
   "<b>Prices per country.</b> Odoo prices incl. 21% are converted to the VAT of the delivery country (OSS).",
   "<b>Payment methods per country</b> through Mollie: Apple Pay, Google Pay, PayPal, Klarna, EPS, MobilePay, TWINT next to card, iDEAL, Bancontact. To be switched on in Mollie.",
   "<b>Free delivery from €300 incl. VAT</b> in BE, NL, FR, DE, LU, with a progress bar in the cart. A proposal; today nothing ships free.",
   "<b>Add-ons</b> in cart and on cable pages: storage bag and the matching plug holder.",
   "<b>Categories</b> in the menu; the live shop shows one flat list of 48 products.",
   "<b>Customer login</b> in the menu and footer, pointing to the Belinus service portal at portal.belinus.com, with a page that explains the portal is shared by all Belinus companies. For the portal build: it must read orders and invoices from the EVChargeking Odoo (evck.odoo.com) as well as the Belinus one; show a company label and filter on every document; keep the EVChargeking logo, Some BV, its VAT number and “A Belinus group company” on the PDF invoices and order confirmations; and the privacy statement must say that the account is shared across the group. The checkout account in this prototype stands for that portal account.",
   "<b>Region and language</b> in one control, modelled on belinus.com, plus a light and dark theme.",
   "<b>Country and language confirmation</b> on the first visit. The prototype reads the browser language and time zone; the live shop should use Odoo's GeoIP country.",
   "<b>Cookie consent</b> with equal Accept and Reject buttons, per-category choice, nothing optional before consent, and a Cookie settings link in the footer to change or withdraw. For the live site: load Google Tag Manager only after consent, keep a consent record, list every cookie in the privacy statement, and host the fonts on your own server instead of loading them from Google. Have the wording checked by a privacy lawyer."])}
  <h2 style="margin:30px 0 12px">VAT and delivery by country</h2><div class="tablewrap"><table class="data"><tr><th>Country</th><th class="n">VAT B2C</th><th>Carrier</th><th class="n">Home excl.</th><th class="n">Pickup excl.</th><th>Free delivery</th><th>Source</th></tr>${ship}</table></div>
  <h2 style="margin:30px 0 12px">Still to confirm <span class="tbc">TO CONFIRM</span></h2>${li([
   "The phone number shown is the one on the Odoo company record. Confirm it is the number customers should call.",
   "Whether the legal entity stays Some BV after the Belinus takeover, for footer, invoices and terms.",
   "DPD rates for countries without a recent order: Italy, Poland, Finland, Czechia, Slovakia, Luxembourg, Switzerland, and the nine EU countries added to complete the list (Bulgaria, Croatia, Cyprus, Estonia, Greece, Latvia, Malta, Romania, Slovenia), which carry a placeholder of €27.50.",
   "Language choice per country shows English plus the official languages (Turkish for Cyprus and Romansh for Switzerland left out). Only Dutch, English and French have full content. The other 22 languages translate the menu, cart, checkout button and the two pop-ups; the rest of the interface and all product texts show in English with a notice in the top bar. These interface translations are machine-made and need a native check, Maltese, Irish and Luxembourgish most of all. Norway and Australia were removed as delivery countries although both had an order this year.",
   "Odoo's OSS VAT rates for Finland (24%), Estonia (20%) and Romania (19%) look outdated; current rates are 25.5%, 24% and 21%.",
   "Photos here were captured from the live site at screen resolution. For the live build, use the original image files from Odoo."])}</div>`;
}

/* ============ LOCALE CONFIRMATION + COOKIE CONSENT ============ */
function renderLocale(){
  // No first-visit pop-up any more: the country only matters at checkout, where the customer chooses it.
  // Until then prices use the country detected from the browser, silently.
  S.locOk=true;
  const m=$("locModal"); if(S.locOk){m.classList.remove("show");return;}
  const cs=Object.keys(SHIP).sort((x,y)=>cname(x).localeCompare(cname(y)));
  m.innerHTML=`<div class="box"><h2 id="locH" style="font-size:1.5rem">${t("loc_h")}</h2><div class="fgrid" style="grid-template-columns:1fr 1fr"><label class="f" for="locC">${t("loc_country")}<select id="locC">${cs.map(c=>`<option value="${c}"${c===S.country?" selected":""}>${esc(cname(c))}</option>`).join("")}</select></label><label class="f" for="locL">${t("loc_lang")}<select id="locL">${SITE_LANGS.map(l=>`<option value="${l}"${l===S.lang?" selected":""}>${LANGN[l]}</option>`).join("")}</select></label></div><p class="note" style="margin:0">${t("loc_prices")}: ${vatLabel()}</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn" data-act="loc-yes">${t("loc_yes")}</button></div></div>`;
  $("locC").onchange=e=>{S.country=e.target.value;save();rerenderKeepingForm();}; $("locL").onchange=e=>{S.lang=e.target.value;save();const u=pathOf(route());if(u!==location.pathname)history.replaceState({},"",u+location.search);rerenderKeepingForm();};
  m.classList.add("show");
}
let ckOpen=false, ckDetail=false;
function renderCookie(){
  const box=$("cookieBox"), show=S.locOk&&(!S.consent||ckOpen); box.classList.toggle("show",show); if(!show)return;
  const c=S.consent||{pref:false,stat:false,mkt:false};
  const row=(k,on,dis)=>`<label class="ck"><input type="checkbox" id="ck-${k}" ${on?"checked":""} ${dis?"disabled":""}><span><b>${t("ck_"+k)}${dis?` · ${t("ck_always")}`:""}</b>${t("ck_"+k+"_d")}</span></label>`;
  box.innerHTML=`<h3 id="ckH" style="font-size:1.15rem">${t("ck_h")}</h3><p>${t("ck_p")} <a href="#privacy" data-act="ck-privacy">${t("ck_more")}</a></p>
  ${ckDetail?`<div>${row("nec",true,true)}${row("pref",c.pref)}${row("stat",c.stat)}${row("mkt",c.mkt)}</div>`:""}
  <div class="acts"><button class="btn even" data-act="ck-reject">${t("ck_reject")}</button><button class="btn even" data-act="ck-accept">${t("ck_accept")}</button></div>
  <button class="textlink" style="justify-self:start" data-act="${ckDetail?"ck-save":"ck-custom"}">${ckDetail?t("ck_save"):t("ck_custom")}</button>`;
}
function setConsent(pref,stat,mkt){S.consent={v:1,at:new Date().toISOString(),pref,stat,mkt}; try{localStorage.setItem("evck-consent",JSON.stringify(S.consent))}catch(e){} ckOpen=false;ckDetail=false;renderCookie(); applyTags();
}
function act(a){
  if(a==="region"){openPanel("r-open");return;}
  if(a==="signin"){window.open(PORTAL,"_blank","noopener");return;}
  if(a==="favs"){S.cat="fav";renderShop();return;}
  if(a==="theme-dark"||a==="theme-light"){S.theme=a.slice(6);applyTheme();save();renderChrome();return;}
  if(a==="theme"){S.theme=curTheme()==="dark"?"light":"dark";applyTheme();save();renderChrome();return;}
  if(a==="cookies"){closeAll();ckOpen=true;ckDetail=true;renderCookie();return;}
  if(a==="loc-yes"){S.locOk=true;save();renderLocale();renderCookie();return;}
  if(a==="loc-open"){closeAll();S.locOk=false;renderLocale();return;}
  if(a==="loc-change"){S.locOk=true;save();renderLocale();renderCookie();openPanel("r-open");return;}
  if(a==="ck-accept"){setConsent(true,true,true);return;}
  if(a==="ck-reject"){setConsent(false,false,false);return;}
  if(a==="ck-custom"){ckDetail=true;renderCookie();return;}
  if(a==="ck-save"){setConsent($("ck-pref").checked,$("ck-stat").checked,$("ck-mkt").checked);return;}
}

/* ============ ROUTER & EVENTS ============ */
function go(){
  let r=route(), view="home", arg=null;
  if(r==="shop"){view="shop";S.cat="all";} else if(r.startsWith("cat-")&&GROUPS.includes(r.slice(4))){view="shop";S.cat=r.slice(4);} else if(/^p-\d+$/.test(r)&&PID[+r.slice(2)]){view="product";arg=+r.slice(2);}
  else if(r==="finder")view="finder"; else if(r==="calc")view="calc"; else if(r==="etappro")view="etappro"; else if(r==="support")view="support"; else if(r==="about")view="about"; else if(r==="account")view="account"; else if(r==="terms"||r==="privacy"){view="legal";arg=r;} else if(r==="checkout")view="checkout"; else if(r==="done")view="done"; else if(r==="paytest")view="paytest";;
  document.querySelectorAll(".view").forEach(v=>v.hidden=v.id!=="v-"+view);
  renderChrome();
  ({home:renderHome,shop:renderShop,product:()=>renderProduct(arg),finder:renderFinder,calc:renderCalc,etappro:renderEtap,support:renderSupport,about:renderAbout,account:renderAccount,legal:()=>renderLegal(arg),checkout:renderCheckout,done:renderDone,paytest:renderPayTest,notes:renderNotes})[view]();
  renderCart(); if(!window.__PRERENDER){renderLocale(); renderCookie();}
  const M=pageMeta(view,arg); dl({event:"page_view",page_path:location.pathname,page_title:M.title});
  if(view==="product")dl({event:"view_item",ecommerce:{currency:"EUR",value:M.product.price,items:[{item_id:String(arg),item_name:PID[arg].n.en}]}}); if(view==="checkout"&&S.cart.length)dl({event:"begin_checkout"});
  document.title=M.title; document.documentElement.lang=urlLang(); window.__meta=M; fixLinks();
}
function pageMeta(view,arg){const B="EVChargeking", pl=(s,n)=>{s=String(s||"").replace(/[#*_>|]/g," ").replace(/\s+/g," ").trim(); return s.length>n?s.slice(0,n-1).replace(/\s+\S*$/,"")+"…":s;};
  const H=L(D.pages.home)[0]; let title=B+" · "+pl(H.h,60), desc=pl(H.p[0],155), r=route(), image="/img/199_big.webp", product=null;
  if(view==="shop"){title=(S.cat==="all"?t("nav_shop"):t("g_"+S.cat))+" · "+B; desc=S.cat==="all"?pl(t("cats_h"),155):pl(t("g_"+S.cat)+": "+t("g_"+S.cat+"_d"),155);}
  else if(view==="product"){const p=PID[arg]; title=L(p.n)+" · "+B; desc=pl(L(p.s)||L(p.d)||L(p.n),155); if(p.i[0])image="/img/"+(p.b||p.i[0])+".webp"; product={id:p.id,name:L(p.n),price:Math.round(gross(p)*100)/100,image:p.i[0]?image:null,stock:p.q>0};}
  else if(view==="finder")title=t("nav_finder")+" · "+B; else if(view==="calc"){const e=evsT(); title=t("calc_btn")+" · "+B; desc=pl(e.h+" "+e.em+" "+e.erB,155); image="/img/etappro-home.jpg";} else if(view==="etappro"){title="ETAPpro · "+B; image="/img/176_big.webp";}
  else if(view==="support"){title=t("nav_support")+" · "+B; desc=pl(t("sup_p"),155);} else if(view==="about")title=t("nav_about")+" · "+B;
  else if(view==="account"){title=t("nav_login")+" · "+B; desc=pl(t("acc_p"),155);} else if(view==="legal")title=(arg==="terms"?t("terms_l"):t("privacy"))+" · "+B;
  else if(view==="checkout")title=t("co_t")+" · "+B; else if(view==="done")title=B; else if(view==="paytest")title=t("tp_eb")+" · "+B;
  const crumbs=[[t("nav_home"),"home"]]; if(view==="shop"||view==="product")crumbs.push([t("nav_shop"),"shop"]); if(view==="shop"&&GROUPS.includes(S.cat))crumbs.push([t("g_"+S.cat),"cat-"+S.cat]);
  if(view==="product"){const p=PID[arg]; crumbs.push([t("g_"+p.g),"cat-"+p.g],[L(p.n),r]); product.until=promoOn(p)?PROMO.until:null; product.images=p.i.map(k=>"/img/"+(k===p.i[0]&&p.b?p.b:k)+".webp"); product.group=t("g_"+p.g);}
  else if(view!=="home"&&view!=="shop")crumbs.push([title.split(" · ")[0],r]);
  const list=view==="shop"?(S.cat==="all"?PR:PR.filter(p=>p.g===S.cat)).map(p=>"p-"+p.id):null;
  const share=view==="product"?"p-"+arg:view==="shop"&&GROUPS.includes(S.cat)?"cat-"+S.cat:view==="etappro"?"etappro":"default";
  return {title,desc,image,product,route:r,crumbs,list,share,noindex:view==="checkout"||view==="done"||view==="paytest"};}
function collectForm(){const o={};document.querySelectorAll("#coForm input").forEach(i=>{if(i.id)o[i.id]=i.type==="checkbox"?i.checked:i.value});return o;}
function restoreForm(o){for(const k in o){const el=$(k);if(!el)continue; if(el.type==="checkbox")el.checked=o[k]; else if(k!=="fVat")el.value=o[k];} renderCoSummary();}
function rerenderKeepingForm(){if(route()==="checkout"&&S.cart.length){const keep=collectForm();renderChrome();renderCheckout();restoreForm(keep);renderCart();} else go();}
function setCountry(c){S.country=c;save();rerenderKeepingForm();}
document.addEventListener("click",e=>{
  const b=e.target.closest("button,a"); if(!b)return; const d=b.dataset;
  if(b.tagName==="A"&&!d.act&&(d.r||(b.getAttribute("href")||"").startsWith("#"))&&!(e.metaKey||e.ctrlKey||e.shiftKey||e.button)){const r=d.r||b.getAttribute("href").slice(1); if(r){e.preventDefault(); if(d.close!==undefined)closeAll(); nav(r); return;}}
  if(d.act){ if(b.tagName==="A"&&d.act!=="ck-privacy")e.preventDefault(); if(d.act!=="ck-privacy")act(d.act); else {e.preventDefault();nav("privacy");} return;}
  if(d.evs){EVS[d.evs]=d.evs==="solar"?+d.v:d.v; document.querySelectorAll('[data-evs="'+d.evs+'"]').forEach(x=>x.setAttribute("aria-pressed",String(x.dataset.v===String(d.v)))); evsOut(); return;}
  if(d.like){const id=+d.like, i=S.likes.indexOf(id); if(i<0)S.likes.push(id); else S.likes.splice(i,1); save(); renderProduct(id); return;}
  if(d.share==="copy"){(navigator.clipboard?navigator.clipboard.writeText(pageUrl()):Promise.reject()).then(()=>toast(t("copied"))).catch(()=>prompt(t("share_copy"),pageUrl())); return;}
  if(d.share==="native"){navigator.share({title:document.title,url:pageUrl()}).catch(()=>{}); return;}
  if(d.sl){S.lang=d.sl;save();closeAll();const u=pathOf(route());if(u!==location.pathname)history.replaceState({},"",u+location.search);rerenderKeepingForm();return;}
  if(d.rc){S.country=d.rc;S.lang=d.rl;save();closeAll();const u=pathOf(route());if(u!==location.pathname)history.replaceState({},"",u+location.search);rerenderKeepingForm();return;}
  if(d.b){S.buyer=d.b; if(S.buyer==="private")S.co.vatValid=false; save(); rerenderKeepingForm(); return;}
  if(d.hc){hero.conn=d.hc;renderBench();return;} if(d.hp){hero.p=d.hp;renderBench();return;}
  if(d.fk){S.fin.kind=d.fk;renderFinder();return;} if(d.fc){S.fin.conn=d.fc;renderFinder();return;} if(d.fp){S.fin.p=d.fp;renderFinder();return;} if(d.fl){S.fin.li=+d.fl;renderFinder();return;} if(d.fcol){S.fin.col=+d.fcol;renderFinder();return;}
  if(d.oa&&d.ov!==undefined){const id=+route().slice(2);selOf(PID[id])[+d.oa]=+d.ov;renderProduct(id);return;}
  if(d.th){const id=+route().slice(2);S.img[id]=+d.th;renderProduct(id);return;}
  if(d.up){addLine(+d.up,[]);return;}
  if(d.q){const l=S.cart[+d.q];l.qty+=+d.d;if(l.qty<1)S.cart.splice(+d.q,1);save();renderCart();if(route()==="checkout")rerenderKeepingForm();return;}
  if(d.rm){S.cart.splice(+d.rm,1);save();renderCart();if(route()==="checkout")rerenderKeepingForm();return;}
  if(d.close!==undefined)closeAll();
});
$("cartBtn").onclick=()=>{closeAll();openCart(true);}; $("closeCart").onclick=closeAll; $("scrim").onclick=closeAll;
$("menuBtn").onclick=()=>openPanel("m-open"); $("regionBtn").onclick=()=>openPanel("r-open"); $("themeBtn").onclick=()=>act("theme");
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeAll()});
if(window.matchMedia)matchMedia("(prefers-color-scheme: dark)").addEventListener?.("change",()=>{if(!S.theme){applyTheme();renderChrome();}});
window.addEventListener("popstate",()=>{closeAll();go();});
new MutationObserver(fixLinks).observe(document.body,{childList:true,subtree:true});
// old "#..." links and the bare domain land on the right page
(function(){const h=location.hash.slice(1), {l}=parsePath(); if(h&&!h.includes("=")){history.replaceState({},"",pathOf(h));} else if(!l){history.replaceState({},"",pathOf(route()));}})();
applyTags();
go();
